from collections import deque


def countBipartiteComponents(n, edges):
    adj = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)
    color = [-1] * n
    count = 0
    for s in range(n):
        if color[s] != -1:
            continue
        color[s] = 0
        ok = True
        queue = deque([s])
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if color[v] == -1:
                    color[v] = 1 - color[u]
                    queue.append(v)
                elif color[v] == color[u]:
                    ok = False
        if ok:
            count += 1
    return count
